-- Register the two immutable author-approved Bach flower reflection forms (EN/RU).
-- Additive only: no historical results, user information, grants or RLS are changed.
-- Original question source: andylitvinov-design/report/src/data/mockData.js.
-- Scoring is implemented server-side in lib/assessments/bach-flower.js.
begin;
do $$
declare
  d jsonb;
begin
  for d in
    select value from jsonb_array_elements($bach_definitions$
[{"id":"e89664f9-1b9d-43a9-8ade-d0b1effc0512","key":"hh-bach-flower","version":"v1","instrumentLocale":"en","translationVersion":"hh-author-source-en-v1","timeframe":"right-now","scoringKey":"bach-remedies","scoringVersion":"v1","resultVersion":"v1","title":"Bach Flower Emotional Self-Reflection","source":{"title":"Andrey Litvinov — original Bach questionnaire (My Alchemist / report)","status":"author-owned-non-validated-self-reflection","citation":"https://github.com/andylitvinov-design/report/blob/main/src/data/mockData.js","reviewedAt":"2026-10-11"},"answerScale":{"min":0,"max":5},"responseAnchors":["Not at all","A little","Sometimes","Strongly","Very strongly","Extremely"],"questions":[{"id":"situation-1","text":"I feel guilty and troubled by remorse.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-2","text":"I doubt my judgment and rely on other people's opinions.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-3","text":"I feel hurt, angry, suspicious, jealous or vengeful.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-4","text":"I feel detached because my thoughts are elsewhere.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-5","text":"Disorder or dirt irritates me; I urgently want things clean.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-6","text":"I feel abandoned and unfairly treated by life.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-7","text":"I feel driven to impose my will on others.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-8","text":"I fear losing myself through change and struggle to begin.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-9","text":"I feel sad or low without knowing why.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-10","text":"I feel inferior, weak or less capable than others.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-11","text":"I keep fighting on despite feeling exhausted.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-12","text":"I am afraid of a particular person or situation.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-13","text":"I am so accommodating that I struggle to say no.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-14","text":"I remain caught up in a past event or relationship.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-15","text":"I feel overwhelmed by responsibilities that seem impossible to meet.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-16","text":"I feel detached and uninvolved with what is happening.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-17","text":"I waver and question whether this is what I want.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-18","text":"I feel impatient because everything seems too slow.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-19","text":"I long for attention, care and emotional support.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-20","text":"I hide my pain behind a cheerful face.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-21","text":"I feel tired and want some peace and rest.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-22","text":"I keep making the same mistakes and feel confused.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-23","text":"Unwanted thoughts and inner arguments wear me down.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-24","text":"I feel trapped, desperate and unsure what to do next.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-25","text":"I take on too much and work beyond my limits.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-26","text":"I feel shocked and unable to process a painful event.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-27","text":"I feel thrown off balance by what is happening.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-28","text":"I feel drained, worn out and completely exhausted.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-29","text":"I push myself relentlessly and allow myself no breaks.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-30","text":"I feel hopeless and resigned to what life brings.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-31","text":"I feel threatened by fears I cannot explain or manage.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-32","text":"I feel hurt and unappreciated when others do not acknowledge me.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-33","text":"I am so concerned about others that I lose touch with my feelings.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-34","text":"I feel discouraged, skeptical and pessimistic.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-35","text":"I feel on the verge of losing control of myself.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-36","text":"I feel tense and overly critical, or unsure when to set limits.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-37","text":"I feel sluggish and lack energy to tackle my tasks.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-38","text":"I feel panicked.","required":true,"section":"situation","direction":"non-normative"},{"id":"character-1","text":"My sense of duty often makes obligations feel burdensome.","required":true,"section":"character","direction":"non-normative"},{"id":"character-2","text":"I underestimate myself and do not trust my own abilities.","required":true,"section":"character","direction":"non-normative"},{"id":"character-3","text":"My need for harmony makes me avoid difficult conversations.","required":true,"section":"character","direction":"non-normative"},{"id":"character-4","text":"I become depleted because I give more than I can.","required":true,"section":"character","direction":"non-normative"},{"id":"character-5","text":"I expect something bad to happen when I consider the future.","required":true,"section":"character","direction":"non-normative"},{"id":"character-6","text":"I am highly critical of myself or others.","required":true,"section":"character","direction":"non-normative"},{"id":"character-7","text":"I have difficulty saying no.","required":true,"section":"character","direction":"non-normative"},{"id":"character-8","text":"I cannot let go of the past.","required":true,"section":"character","direction":"non-normative"},{"id":"character-9","text":"Even small problems feel like a heavy mountain before I start.","required":true,"section":"character","direction":"non-normative"},{"id":"character-10","text":"I fear that expressing feelings would make me lose control.","required":true,"section":"character","direction":"non-normative"},{"id":"character-11","text":"I become suspicious, jealous or aggressive easily.","required":true,"section":"character","direction":"non-normative"},{"id":"character-12","text":"I doubt whether I truly want what I am pursuing.","required":true,"section":"character","direction":"non-normative"},{"id":"character-13","text":"I repeatedly blame myself afterward.","required":true,"section":"character","direction":"non-normative"},{"id":"character-14","text":"I feel too emotionally vulnerable to face certain circumstances.","required":true,"section":"character","direction":"non-normative"},{"id":"character-15","text":"I keep switching between decisions and cannot choose.","required":true,"section":"character","direction":"non-normative"},{"id":"character-16","text":"My sense of duty makes me keep going regardless of cost.","required":true,"section":"character","direction":"non-normative"},{"id":"character-17","text":"I overexert myself and sometimes overwhelm others with my intensity.","required":true,"section":"character","direction":"non-normative"},{"id":"character-18","text":"My sense of injustice makes it hard to let things go.","required":true,"section":"character","direction":"non-normative"},{"id":"character-19","text":"I keep asking others to confirm that I am right.","required":true,"section":"character","direction":"non-normative"},{"id":"character-20","text":"I panic quickly and my mind goes blank.","required":true,"section":"character","direction":"non-normative"},{"id":"character-21","text":"I impose strict discipline and very high demands on myself.","required":true,"section":"character","direction":"non-normative"},{"id":"character-22","text":"My ambition makes me try to impose my will.","required":true,"section":"character","direction":"non-normative"},{"id":"character-23","text":"I become anxious if every detail is not perfectly in order.","required":true,"section":"character","direction":"non-normative"},{"id":"character-24","text":"I feel hopeless and see little purpose ahead.","required":true,"section":"character","direction":"non-normative"},{"id":"character-25","text":"I withdraw inward and have trouble noticing others.","required":true,"section":"character","direction":"non-normative"},{"id":"character-26","text":"I drift into thoughts far removed from what is happening.","required":true,"section":"character","direction":"non-normative"},{"id":"character-27","text":"I find even a short wait extremely difficult.","required":true,"section":"character","direction":"non-normative"},{"id":"character-28","text":"I absorb other people's feelings and struggle to keep boundaries.","required":true,"section":"character","direction":"non-normative"},{"id":"character-29","text":"Low mood can leave me unable to act.","required":true,"section":"character","direction":"non-normative"},{"id":"character-30","text":"I often feel apathetic and disengaged.","required":true,"section":"character","direction":"non-normative"},{"id":"character-31","text":"I tend to retreat and find teamwork difficult.","required":true,"section":"character","direction":"non-normative"},{"id":"character-32","text":"Repetitive thoughts make it hard to focus.","required":true,"section":"character","direction":"non-normative"},{"id":"character-33","text":"I rely on others to support my plans because I distrust myself.","required":true,"section":"character","direction":"non-normative"},{"id":"character-34","text":"I keep repeating mistakes because I miss important details.","required":true,"section":"character","direction":"non-normative"},{"id":"character-35","text":"I assume things will not work out.","required":true,"section":"character","direction":"non-normative"},{"id":"character-36","text":"I carry excessive responsibility.","required":true,"section":"character","direction":"non-normative"},{"id":"character-37","text":"I expect gratitude for intervening in other people's affairs.","required":true,"section":"character","direction":"non-normative"},{"id":"character-38","text":"I let events drift until I feel stuck.","required":true,"section":"character","direction":"non-normative"},{"id":"character-39","text":"I feel bitter and powerless in the face of circumstances.","required":true,"section":"character","direction":"non-normative"},{"id":"control-1","text":"Fear or timidity.","required":true,"section":"control","direction":"non-normative"},{"id":"control-2","text":"Low self-esteem or feelings of inferiority.","required":true,"section":"control","direction":"non-normative"},{"id":"control-3","text":"Seeking harmony at almost any cost.","required":true,"section":"control","direction":"non-normative"},{"id":"control-4","text":"Lack of energy or exhaustion.","required":true,"section":"control","direction":"non-normative"},{"id":"control-5","text":"Fear without a clear explanation.","required":true,"section":"control","direction":"non-normative"},{"id":"control-6","text":"Trouble with tolerance or criticism.","required":true,"section":"control","direction":"non-normative"},{"id":"control-7","text":"Kindness combined with difficulty setting boundaries.","required":true,"section":"control","direction":"non-normative"},{"id":"control-8","text":"Being focused on the past.","required":true,"section":"control","direction":"non-normative"},{"id":"control-9","text":"Feeling overloaded and internally sluggish.","required":true,"section":"control","direction":"non-normative"},{"id":"control-10","text":"Emotions building up under pressure.","required":true,"section":"control","direction":"non-normative"},{"id":"control-11","text":"Distrust, envy or anger.","required":true,"section":"control","direction":"non-normative"},{"id":"control-12","text":"Uncertainty about the direction of my life.","required":true,"section":"control","direction":"non-normative"},{"id":"control-13","text":"Guilt or remorse.","required":true,"section":"control","direction":"non-normative"},{"id":"control-14","text":"Emotional sensitivity or vulnerability.","required":true,"section":"control","direction":"non-normative"},{"id":"control-15","text":"Indecision.","required":true,"section":"control","direction":"non-normative"},{"id":"control-16","text":"Pursuing a goal at any cost.","required":true,"section":"control","direction":"non-normative"},{"id":"control-17","text":"Excessive zeal or intensity.","required":true,"section":"control","direction":"non-normative"},{"id":"control-18","text":"Doubting my own judgment.","required":true,"section":"control","direction":"non-normative"},{"id":"control-19","text":"Sudden internal panic.","required":true,"section":"control","direction":"non-normative"},{"id":"control-20","text":"Excessive self-discipline.","required":true,"section":"control","direction":"non-normative"},{"id":"control-21","text":"Being overly focused on myself.","required":true,"section":"control","direction":"non-normative"},{"id":"control-22","text":"Excessive concern about cleanliness or imperfections.","required":true,"section":"control","direction":"non-normative"},{"id":"control-23","text":"Pessimism about the future.","required":true,"section":"control","direction":"non-normative"},{"id":"control-24","text":"Withdrawing into myself.","required":true,"section":"control","direction":"non-normative"},{"id":"control-25","text":"Avoiding the realities of the present.","required":true,"section":"control","direction":"non-normative"},{"id":"control-26","text":"Impatience.","required":true,"section":"control","direction":"non-normative"},{"id":"control-27","text":"Excessive concern for others.","required":true,"section":"control","direction":"non-normative"},{"id":"control-28","text":"Low mood that feels paralyzing.","required":true,"section":"control","direction":"non-normative"},{"id":"control-29","text":"Inner apathy or indifference.","required":true,"section":"control","direction":"non-normative"},{"id":"control-30","text":"Tendency to isolate or withdraw.","required":true,"section":"control","direction":"non-normative"},{"id":"control-31","text":"Unwanted recurring thoughts.","required":true,"section":"control","direction":"non-normative"},{"id":"control-32","text":"Feeling unstable or without inner grounding.","required":true,"section":"control","direction":"non-normative"},{"id":"control-33","text":"Making the same mistakes automatically.","required":true,"section":"control","direction":"non-normative"},{"id":"control-34","text":"Expecting something bad to happen.","required":true,"section":"control","direction":"non-normative"},{"id":"control-35","text":"Excessive sense of responsibility.","required":true,"section":"control","direction":"non-normative"},{"id":"control-36","text":"Being demanding or trying to manipulate situations.","required":true,"section":"control","direction":"non-normative"},{"id":"control-37","text":"Feeling there is no way out in extreme situations.","required":true,"section":"control","direction":"non-normative"},{"id":"control-38","text":"Bitterness or resentment.","required":true,"section":"control","direction":"non-normative"}],"optionalContext":[],"suggestedRepeatDays":14,"contentHash":"sha256:9df0414210456a9c0223a118a97e8cfdd40488d8e90496b5de74db046ef4ea7d"},{"id":"0c8af245-93b4-4db7-a5bf-d180bbfbb632","key":"hh-bach-flower","version":"v1","instrumentLocale":"ru","translationVersion":"hh-author-source-ru-v1","timeframe":"right-now","scoringKey":"bach-remedies","scoringVersion":"v1","resultVersion":"v1","title":"Цветочные эссенции Баха · самоанализ","source":{"title":"Andrey Litvinov — original Bach questionnaire (My Alchemist / report)","status":"author-owned-non-validated-self-reflection","citation":"https://github.com/andylitvinov-design/report/blob/main/src/data/mockData.js","reviewedAt":"2026-10-11"},"answerScale":{"min":0,"max":5},"responseAnchors":["Не про меня","Едва заметно","Иногда","Выражено","Очень сильно","Максимально"],"questions":[{"id":"situation-1","text":"Я чувствую себя виноватой(ым). Меня терзают угрызения совести.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-2","text":"Я чувствую себя неуверенно. Я сомневаюсь вправе ли я судить и ориентируюсь на чужое мнение.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-3","text":"Я чувствую себя задетой(ым), гневной(ым), подозрительной(ым), ревнивой(ым), мстительной(ым).","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-4","text":"Я чувствую себя не особенно тронутой(ым) ситуацией, так как постоянно витаю мыслями где-то в другом месте.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-5","text":"Я чувствую себя раздраженной(ым) отсутствием порядка, грязной(ым), мне противно, мне необходима чистота.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-6","text":"Я чувствую себя брошенной(ым) на произвол судьбы, несправедливо обиженной(ым) ею.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-7","text":"Я чувствую себя вынужденной(ым) навязать свою волю.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-8","text":"Я чувствую себя недостаточно стойкой(им). Я боюсь изменить самой(му) себе. Я хочу приняться за дело.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-9","text":"Я чувствую себя меланхоличной(ым), грустной(ым), в депрессии, не зная, почему.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-10","text":"Я чувствую себя неполноценной(ым), слабой(ым), менее способной(ым), чем другие люди.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-11","text":"Я чувствую себя изможденным бойцом на посту, которому нельзя сдаваться.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-12","text":"Я чувствую себя напуганной(ым). Я боюсь конкретного человека или конкретного события.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-13","text":"Я чувствую себя слишком мягкой(им), слишком добросердечной(ым), я не могу сказать «нет».","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-14","text":"Я чувствую себя унылой(ым). Я не могу избавиться от прошлого: события или отношения.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-15","text":"Я чувствую себя перегруженной(ым) своей ответственностью. Я просто не могу все это сделать!","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-16","text":"Я чувствую себя не принимающей(им) участие. Я отстранилась от всего этого.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-17","text":"Я чувствую себя нерешительной(ым), раздробленной(ым), сомневающейся(имся). Действительно ли это то, чего я хочу?","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-18","text":"Я чувствую себя нетерпеливой(ым). Все мне кажется слишком медленно происходящим.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-19","text":"Я чувствую себя духовно нуждающейся(имся), мне необходимы участие и поддержка.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-20","text":"Я чувствую себя клоуном, делающим хорошую мину при плохой игре.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-21","text":"Я чувствую себя уставшей(им), хочу покоя.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-22","text":"Я чувствую себя озадаченной(ым), так как постоянно совершаю одни и те же ошибки.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-23","text":"Я чувствую себя измученной(ым) нежеланными мыслями и внутренними диалогами, от которых не могу избавиться.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-24","text":"Я чувствую себя зажатой(ым) в тиски, отчаявшейся(имся), не знаю, что делать дальше.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-25","text":"Я чувствую себя занятой(ым) на сто пятьдесят процентов.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-26","text":"Я чувствую себя полностью шокированной(ым), я никак не могу справиться с этим ударом судьбы.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-27","text":"Я чувствую себя выбитой(ым) из равновесия.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-28","text":"Я чувствую себя обессиленной(ым), измученной(ым), истощенной(ым).","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-29","text":"Я чувствую себя рекордсменом, вынужденным постоянно тренироваться, ничего себе не позволять.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-30","text":"Я чувствую себя лишенной(ым) надежды, покоренной(ым) судьбе.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-31","text":"Я чувствую себя подверженной(ым) угрозе, меня одолевают страхи, с которыми я не могу справиться.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-32","text":"Я чувствую себя недостаточно оценимой(ым) или любимой(ым), раненой(ым), разочарованной(ым), так как я ожидала большего признания или благодарности.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-33","text":"Я чувствую себя так сильно погруженной(ым) в положение других людей, что практически не воспринимаю свои собственные чувства и страхи.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-34","text":"Я чувствую себя обескураженной(ым), настроенной(ым) скептически и пессимистически.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-35","text":"Я чувствую себя как на бочке с порохом. Я больше не могу владеть собой.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-36","text":"Я чувствую себя нервной(ым), слишком критичной(ым) или, наоборот, некритичной(ым), терпимой(ым).","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-37","text":"Я чувствую себя внутренне вялой, лишенной(ым) энергии. У меня недостаточно сил, чтобы выполнить мое задание.","required":true,"section":"situation","direction":"non-normative"},{"id":"situation-38","text":"Я чувствую себя в панике.","required":true,"section":"situation","direction":"non-normative"},{"id":"character-1","text":"Мне мешает моя обязательность: я боюсь, что всё это доставит мне слишком много хлопот.","required":true,"section":"character","direction":"non-normative"},{"id":"character-2","text":"Мне мешает моя недооценка самой себя: я просто не доверяю самой(ому) себе.","required":true,"section":"character","direction":"non-normative"},{"id":"character-3","text":"Мне мешает моя слишком сильная потребность в гармонии: я не хочу некрасивых дискуссий и споров.","required":true,"section":"character","direction":"non-normative"},{"id":"character-4","text":"Мне мешает мой недостаток силы: я полностью выложился(ась), это слишком много для меня.","required":true,"section":"character","direction":"non-normative"},{"id":"character-5","text":"Мне мешает мое повышенное «чутье»: когда я думаю о чем-либо, у меня появляются плохие предчувствия.","required":true,"section":"character","direction":"non-normative"},{"id":"character-6","text":"Мне мешает моя непростительная склонность к критике и самокритике: многое мешает мне, но я не могу перепрыгнуть через свою голову.","required":true,"section":"character","direction":"non-normative"},{"id":"character-7","text":"Мне мешает моя слабая воля: я просто не могу сказать «нет».","required":true,"section":"character","direction":"non-normative"},{"id":"character-8","text":"Мне мешает моя сильная зависимость от прошлого: я просто не могу забыть то, что было раньше.","required":true,"section":"character","direction":"non-normative"},{"id":"character-9","text":"Мне мешает недостаток внутренней энергии: когда я думаю о какой-либо проблеме, она предстает передо мной в виде огромной серой горы.","required":true,"section":"character","direction":"non-normative"},{"id":"character-10","text":"Мне мешает страх перед моими собственными чувствами: если я отпущу себя, я больше не смогу себя контролировать.","required":true,"section":"character","direction":"non-normative"},{"id":"character-11","text":"Мне мешает моя подозрительность, моя ничем не обоснованная ревность: я быстро становлюсь агрессивным(ой).","required":true,"section":"character","direction":"non-normative"},{"id":"character-12","text":"Мне мешает моя внутренняя нерешительность: я не знаю, хочу ли я этого в действительности.","required":true,"section":"character","direction":"non-normative"},{"id":"character-13","text":"Мне мешают мои постоянные угрызения совести: я знаю, что снова буду себя упрекать.","required":true,"section":"character","direction":"non-normative"},{"id":"character-14","text":"Мне мешает моя душевная ранимость: у меня просто не хватает сил справиться с определенными обстоятельствами.","required":true,"section":"character","direction":"non-normative"},{"id":"character-15","text":"Мне мешает моя постоянная нерешительность: сначала мне кажется, что лучше всего подходит одно решение, потом — другое.","required":true,"section":"character","direction":"non-normative"},{"id":"character-16","text":"Мне мешает мое избыточное чувство долга: я обязан(а) довести всё до конца.","required":true,"section":"character","direction":"non-normative"},{"id":"character-17","text":"Мне мешает мой напор, мое рвение: я знаю, что снова буду выкладываться на сто пятьдесят процентов и даже действовать другим на нервы.","required":true,"section":"character","direction":"non-normative"},{"id":"character-18","text":"Мне мешает мое сильное чувство справедливости: я не могу просто так это оставить.","required":true,"section":"character","direction":"non-normative"},{"id":"character-19","text":"Мне мешает мое внутреннее чувство неуверенности: я снова и снова спрашиваю других людей, чтобы увериться в чем-либо.","required":true,"section":"character","direction":"non-normative"},{"id":"character-20","text":"Мне мешает моя склонность моментально впадать в панику: когда я думаю об этом, моя голова пустеет.","required":true,"section":"character","direction":"non-normative"},{"id":"character-21","text":"Мне мешает моя склонность к строгой дисциплине: я слишком строг(а) к самой(ому) себе, слишком много от себя требую.","required":true,"section":"character","direction":"non-normative"},{"id":"character-22","text":"Мне мешает мое честолюбие: я должна(ен) всегда навязывать свою волю.","required":true,"section":"character","direction":"non-normative"},{"id":"character-23","text":"Мне мешают моя педантичность, мое стремление к чистоте: даже самые маленькие мелочи должны быть в порядке, иначе я нервничаю.","required":true,"section":"character","direction":"non-normative"},{"id":"character-24","text":"Мне мешает мое чувство безнадежности: я думаю, что больше нет никакого смысла.","required":true,"section":"character","direction":"non-normative"},{"id":"character-25","text":"Мне мешает моя углубленность внутрь себя: я просто не воспринимаю других людей.","required":true,"section":"character","direction":"non-normative"},{"id":"character-26","text":"Мне мешает мой недостаточный интерес к реальным ситуациям, так как я поглощен(а) мыслями об абсолютно других вещах.","required":true,"section":"character","direction":"non-normative"},{"id":"character-27","text":"Мне мешает моя нетерпеливость: я просто не могу ждать ни минуты.","required":true,"section":"character","direction":"non-normative"},{"id":"character-28","text":"Мне мешает мое слишком сильное сострадание: я точно знаю, что чувствует другой человек, и не могу оградить себя от этого.","required":true,"section":"character","direction":"non-normative"},{"id":"character-29","text":"Мне мешает мой меланхоличный настрой: иногда он меня даже парализует.","required":true,"section":"character","direction":"non-normative"},{"id":"character-30","text":"Мне мешает мое практически апатичное безучастие: мне всё безразлично, я отгородился(ась) от всего этого.","required":true,"section":"character","direction":"non-normative"},{"id":"character-31","text":"Мне мешает моя «склонность к отступлению»: мне тяжело работать с другими людьми.","required":true,"section":"character","direction":"non-normative"},{"id":"character-32","text":"Мне мешает продолжительная карусель мыслей: я не могу сконцентрироваться на самом важном.","required":true,"section":"character","direction":"non-normative"},{"id":"character-33","text":"Мне мешает моя неустойчивость: в моих планах меня должна всегда поддерживать третья сторона, я не верю самой(ому) себе.","required":true,"section":"character","direction":"non-normative"},{"id":"character-34","text":"Мне мешает моя невнимательность: я постоянно допускаю одни и те же ошибки.","required":true,"section":"character","direction":"non-normative"},{"id":"character-35","text":"Мне мешает мой скептический настрой: собственно говоря, я уже не жду, что что-либо получится.","required":true,"section":"character","direction":"non-normative"},{"id":"character-36","text":"Мне мешает мое слишком сильное чувство ответственности.","required":true,"section":"character","direction":"non-normative"},{"id":"character-37","text":"Мне мешает моя позиция ожидания: я вмешиваюсь не в свое дело и жду за это благодарности.","required":true,"section":"character","direction":"non-normative"},{"id":"character-38","text":"Мне мешает моя склонность пускать дело на самотек и потом не находить выхода из сложившейся ситуации.","required":true,"section":"character","direction":"non-normative"},{"id":"character-39","text":"Мне мешает моя озлобленность: я чувствую себя бессильной жертвой обстоятельств.","required":true,"section":"character","direction":"non-normative"},{"id":"control-1","text":"Боязливость, страх","required":true,"section":"control","direction":"non-normative"},{"id":"control-2","text":"Заниженная самооценка или комплекс неполноценности","required":true,"section":"control","direction":"non-normative"},{"id":"control-3","text":"Поиск гармонии","required":true,"section":"control","direction":"non-normative"},{"id":"control-4","text":"Недостаток силы / истощение","required":true,"section":"control","direction":"non-normative"},{"id":"control-5","text":"Необъяснимое чувство страха","required":true,"section":"control","direction":"non-normative"},{"id":"control-6","text":"Проблема с терпимостью","required":true,"section":"control","direction":"non-normative"},{"id":"control-7","text":"Добросердечие и слабая воля","required":true,"section":"control","direction":"non-normative"},{"id":"control-8","text":"Направленность в прошлое","required":true,"section":"control","direction":"non-normative"},{"id":"control-9","text":"Чувство перегруженности, внутренняя вялость","required":true,"section":"control","direction":"non-normative"},{"id":"control-10","text":"Давление чувств","required":true,"section":"control","direction":"non-normative"},{"id":"control-11","text":"Отрицательные чувства: недоверие, зависть, ярость","required":true,"section":"control","direction":"non-normative"},{"id":"control-12","text":"Неуверенность в выборе жизненного пути","required":true,"section":"control","direction":"non-normative"},{"id":"control-13","text":"Угрызения совести","required":true,"section":"control","direction":"non-normative"},{"id":"control-14","text":"Внутренняя ранимость","required":true,"section":"control","direction":"non-normative"},{"id":"control-15","text":"Нерешительность","required":true,"section":"control","direction":"non-normative"},{"id":"control-16","text":"Достижение цели любой ценой","required":true,"section":"control","direction":"non-normative"},{"id":"control-17","text":"Чрезмерное рвение","required":true,"section":"control","direction":"non-normative"},{"id":"control-18","text":"Внутренняя неуверенность","required":true,"section":"control","direction":"non-normative"},{"id":"control-19","text":"Внутренняя паника","required":true,"section":"control","direction":"non-normative"},{"id":"control-20","text":"Чрезмерная самодисциплина","required":true,"section":"control","direction":"non-normative"},{"id":"control-21","text":"Эгоистический настрой","required":true,"section":"control","direction":"non-normative"},{"id":"control-22","text":"Чрезмерная чистоплотность, брезгливость","required":true,"section":"control","direction":"non-normative"},{"id":"control-23","text":"Унылые перспективы","required":true,"section":"control","direction":"non-normative"},{"id":"control-24","text":"Углубленность внутрь себя, уход в себя","required":true,"section":"control","direction":"non-normative"},{"id":"control-25","text":"Неприятие реальности","required":true,"section":"control","direction":"non-normative"},{"id":"control-26","text":"Нетерпеливость","required":true,"section":"control","direction":"non-normative"},{"id":"control-27","text":"Чрезмерное сострадание","required":true,"section":"control","direction":"non-normative"},{"id":"control-28","text":"Парализующая меланхолия","required":true,"section":"control","direction":"non-normative"},{"id":"control-29","text":"Внутренняя апатия","required":true,"section":"control","direction":"non-normative"},{"id":"control-30","text":"Изоляция, склонность к отступлению","required":true,"section":"control","direction":"non-normative"},{"id":"control-31","text":"Мысленный мусор","required":true,"section":"control","direction":"non-normative"},{"id":"control-32","text":"Неустойчивость","required":true,"section":"control","direction":"non-normative"},{"id":"control-33","text":"Автоматические ошибки","required":true,"section":"control","direction":"non-normative"},{"id":"control-34","text":"Ожидание чего-то плохого","required":true,"section":"control","direction":"non-normative"},{"id":"control-35","text":"Чрезмерное чувство ответственности","required":true,"section":"control","direction":"non-normative"},{"id":"control-36","text":"Повышенные претензии, стремление к тактическим маневрам","required":true,"section":"control","direction":"non-normative"},{"id":"control-37","text":"Чувство безвыходности в экстремальных ситуациях","required":true,"section":"control","direction":"non-normative"},{"id":"control-38","text":"Озлобленность","required":true,"section":"control","direction":"non-normative"}],"optionalContext":[],"suggestedRepeatDays":14,"contentHash":"sha256:2a60d7f2bbda2b203bf96baf41176f29750525e78c1971956811c029cb1f2a4c"}]
$bach_definitions$::jsonb)
  loop
    if exists (
      select 1 from app.assessment_versions
      where id = (d->>'id')::uuid
        and (content_hash <> d->>'contentHash' or definition <> d)
    ) then
      raise exception 'Bach questionnaire % differs from immutable version', d->>'id';
    end if;
    insert into app.assessment_versions (
      id, definition_key, definition_version, instrument_locale, translation_version,
      definition, questions, answer_schema, scoring_key, scoring_version,
      result_schema, timeframe, source_metadata, content_hash
    ) values (
      (d->>'id')::uuid, d->>'key', d->>'version', d->>'instrumentLocale', d->>'translationVersion',
      d, d->'questions', jsonb_build_object(
        'type', 'integer',
        'minimum', (d->'answerScale'->>'min')::int,
        'maximum', (d->'answerScale'->>'max')::int
      ),
      d->>'scoringKey', d->>'scoringVersion',
      jsonb_build_object('version', d->>'resultVersion'),
      d->>'timeframe', d->'source', d->>'contentHash'
    ) on conflict(id) do nothing;
  end loop;
end $$;
commit;
